CREATE TABLE incoming_albums (
  bot_id TEXT NOT NULL, chat_id INTEGER NOT NULL, media_group_id TEXT NOT NULL,
  request_id INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'collecting',
  revision INTEGER NOT NULL DEFAULT 0, ready_at INTEGER NOT NULL,
  PRIMARY KEY (bot_id, chat_id, media_group_id)
);
CREATE TABLE album_items (
  bot_id TEXT NOT NULL, chat_id INTEGER NOT NULL, message_id INTEGER NOT NULL,
  media_group_id TEXT NOT NULL, file_id TEXT NOT NULL, caption TEXT NOT NULL,
  PRIMARY KEY (bot_id, chat_id, message_id)
);
